import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/12-Computers-can-learn-by-themselves.html","title":"12- 计算机的“自我学习课”","lang":"zh-CN","frontmatter":{"title":"12- 计算机的“自我学习课”","icon":"read","date":"2025-04-15T08:25:31.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":17,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"5ee0246ead0b12447ecb3ed36550ab77e99a789c","time":1744703858000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"膝盖图片"},{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"826171bacf6309ec9b413341fac10519f0bf0ad0","time":1744695842000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"ab2331ca464b196227eb514354a3445ba03bb484","time":1744687581000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"差图片"},{"hash":"22d63cbcbec83a52865149cc4003dfbb5fe6bf46","time":1744686052000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"聚类（Clustering）"},{"hash":"558cbf04c4cb5af8b6459ac9556eb77a353e4408","time":1744676762000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":5.32,"words":1597},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/12-Computers-can-learn-by-themselves.md"}`),a={name:`12-Computers-can-learn-by-themselves.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在学校，很多同学都体验过早自习或晚自习的时光。那是一段没有老师讲课、需要自己安排时间看书、做题、复习的时间。可你有没有想过，<strong>计算机也会“自学”</strong>？</p><p>这听起来是不是有点离谱？计算机也要像我们一样上“自习”？那它是不是也要考试、交作业？其实，咱们今天要聊的，就是关于计算机“自我学习”的故事。</p><h2 id="_1-冰箱里的任务" tabindex="-1"><a class="header-anchor" href="#_1-冰箱里的任务"><span>1. 冰箱里的任务</span></a></h2><figure><img src="/assets/raw-20250415091915316-UaFJOUB1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>想象一下，面前有一台冰箱。你打开它的门，里面塞满了各种食物：苹果、西兰花、牛肉、果汁……如果现在请你给这些东西<strong>归个类</strong>，是不是非常轻松？</p><p>你或许会把<strong>水果和蔬菜分开</strong>，把<strong>饮料和肉类分开</strong>，甚至还能再细致些，把蔬菜分成叶子类和根茎类，水果按味道分成甜的和酸的。这种分类任务，我们从小就已经很熟悉了，不需要人特意教，就能顺利完成。</p><figure><img src="/assets/raw-20250415105453683-J48Z2uX2.png" alt="监督学习图示" tabindex="0" loading="lazy"><figcaption>监督学习图示</figcaption></figure><p>其实这类任务，计算机也能做到。它只需要我们喂给它足够多的样本图片，再告诉它哪些是水果，哪些是蔬菜，它就能学会。这个过程叫做“<strong>监督学习</strong>”，也就是<strong>在人类的指导下学习</strong>。</p><h3 id="_2-来到未知的星球" tabindex="-1"><a class="header-anchor" href="#_2-来到未知的星球"><span>2. 来到未知的星球</span></a></h3><figure><img src="/assets/kkk-DuX7fGzS.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>好，现在换个更刺激的场景。假设你是一名宇航员，登陆了一颗遥远的陌生星球。这里的植物和果子五花八门：有三角形的果实，有长得像五角星的，还有各种奇怪的颜色，比如蓝色、粉红、橙色……</p><p>指挥中心忽然传来命令：“请将这些外星果子进行分类！”</p><p>你会不会有点懵？这些果子既不像苹果，也不像香蕉，完全看不懂。但你可能还是能找到思路，比如——</p><ul><li><strong>按颜色来分</strong>，同一色系放一堆；</li><li><strong>按形状来分</strong>，差不多形状的放一块；</li></ul><p>虽然你不知道这些果子的名字，但你依然能基于<strong>外在特征</strong>进行归类。这其实是一种非常重要的能力，也正是<strong>计算机自学的核心方式</strong>。</p><h2 id="_3-分类-vs-聚类" tabindex="-1"><a class="header-anchor" href="#_3-分类-vs-聚类"><span>3. 分类 Vs. 聚类</span></a></h2><p>你或许会想：这种给东西分门别类的行为不就是“分类”吗？</p><p>其实还真不一样！</p><figure><img src="/assets/%E5%88%86%E7%B1%BB-jsf3Zbyf.png" alt="分类（Classification）" tabindex="0" loading="lazy"><figcaption>分类（Classification）</figcaption></figure><p>在前面冰箱的例子中，我们是知道每一样东西的名称和类别的，这种<strong>明确知道</strong>“答案”的情况，叫做<strong>分类（Classification）</strong>。</p><figure><img src="/assets/llll-DGROhO78.png" alt="聚类（Clustering）" tabindex="0" loading="lazy"><figcaption>聚类（Clustering）</figcaption></figure><figure><img src="/assets/%E6%96%B9%E6%B3%95-DiruEA8o.png" alt="聚类（Clustering）" tabindex="0" loading="lazy"><figcaption>聚类（Clustering）</figcaption></figure><p>而在外星球的情况里，我们<strong>完全不知道</strong>那些果子是什么，只能靠猜测和特征去分组，这种“靠特征找规律”的方式，叫做<strong>聚类（Clustering）</strong>。聚类的意思，就是根据一些特征把不同的东西聚在一块。（物以类聚，人以群分）</p><p>分类是老师手把手教你做题，聚类更像是你自己看着例题慢慢琢磨规律。</p><h2 id="_4-计算机怎么-自己学" tabindex="-1"><a class="header-anchor" href="#_4-计算机怎么-自己学"><span>4. 计算机怎么“自己学”？</span></a></h2><p>在没有人类指导的情况下，计算机要学会像你一样对外星果子做聚类。就必须先对它们进行<strong>抽象</strong>，也就是把果子的特征变成<strong>数字</strong>：</p><ol><li><p>红色的果子可能用数字 <code>1</code> 表示，蓝色的记作 <code>2</code>，淡蓝色则可能是 <code>1.8</code>；</p></li><li><p>三角形的形状设为 <code>1</code>，五角星形状设为 <code>2</code>，介于两者之间的形状或许是 <code>1.5</code>；</p></li></ol><p>每一个果子都会被表示成一组数字，像 <code>[1.2, 2.0]</code> 这样的数据点。然后计算机会根据这些数字之间的“相似度”，把差不多的放在一组，不同的归到不同类里。这就是计算机的“自习”。</p><h2 id="_5-无监督学习登场" tabindex="-1"><a class="header-anchor" href="#_5-无监督学习登场"><span>5. 无监督学习登场</span></a></h2><figure><img src="/assets/%E6%97%A0%E7%9B%91%E7%9D%A3%E5%AD%A6%E4%B9%A0-DcvVfJa6.png" alt="无监督学习" tabindex="0" loading="lazy"><figcaption>无监督学习</figcaption></figure><figure><img src="/assets/csccccs-aL6d_hGk.png" alt="无监督学习" tabindex="0" loading="lazy"><figcaption>无监督学习</figcaption></figure><p>这种没有人类老师参与，只靠数据特征来自我判断归类的学习方式，在人工智能领域里有个名字，叫做：<strong>无监督学习（Unsupervised Learning）</strong>。</p><p>你可能会好奇，这种学习到底有没有用？实际上，在面对<strong>人类自己也搞不明白的问题</strong>时，无监督学习就显得特别强大。</p><p>比如科学家研究某些新发现的微生物时，完全不知道它们属于哪种类型。这时候，就可以先交给计算机分析，让它先“看一圈”，把形状相近、基因类似的微生物归为一类，再由人类科学家进一步研究。（省字版：<strong>计算机替我们总结一个初步的规律，人类在此基础上做进一步研究</strong>。）</p><p>无监督学习就像一位擅长“扫盲”的助手，能在一切混乱中先帮我们找到些许秩序。</p><h2 id="_6-最重要的启发-不断调整" tabindex="-1"><a class="header-anchor" href="#_6-最重要的启发-不断调整"><span>6. 最重要的启发：不断调整</span></a></h2><figure><img src="/assets/111111-B4lpxy4v.png" alt="无监督学习是动态的" tabindex="0" loading="lazy"><figcaption>无监督学习是动态的</figcaption></figure><p>还有一点值得你特别注意：<strong>无监督学习是动态的</strong>。</p><p>每当计算机见到一个新果子，它都要判断这个新果子该归到哪类，或者是不是需要新建一个分类。就像我们学习的过程中，不断根据考试结果、复习效率来调整复习计划。</p><p>你可能一开始每天背三门课，每门半小时，但随着进度不同、掌握情况不同，你会慢慢把时间分配得更合理。<strong>不断优化，不断试错，不断修正</strong>——这才是学习的本质。（省字版：<strong>根据实际情况不断优化调整，以达到最佳效果</strong>。）</p><p>所以你看，计算机也能像我们一样，不需要人盯着教，靠着自己总结规律，慢慢变聪明。</p><p>至于它会不会聪明到和人类一样？有没有可能发展出真正的“智慧”？这个问题，我后面继续讨论！</p>`,42)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};